DROP TABLE IF EXISTS `final_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `final_transactions` (
  `transaction_id` char(8) NOT NULL,
  `company_id` char(8) DEFAULT NULL,
  `material_id` char(8) DEFAULT NULL,
  `quantity` decimal(10,2) DEFAULT NULL,
  `price_per_unit` decimal(10,2) DEFAULT NULL,
  `discount_rate` int DEFAULT NULL,
  `total_price` decimal(12,2) DEFAULT NULL,
  `transaction_date` date DEFAULT NULL,
  `notes` text,
  PRIMARY KEY (`transaction_id`),
  KEY `company_id` (`company_id`),
  KEY `material_id` (`material_id`),
  CONSTRAINT `final_transactions_ibfk_1` FOREIGN KEY (`company_id`) REFERENCES `final_companies` (`company_id`),
  CONSTRAINT `final_transactions_ibfk_2` FOREIGN KEY (`material_id`) REFERENCES `final_materials` (`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
